head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// DrillDown GridView 는 기본적으로 Row DragDrop 이 동작하지 않으므로 양쪽 그리드에 활성화한다.
scwin.onpageload = function () {
    $p.getComponentById("target1").setDrillDownDragDrop(true);
    $p.getComponentById("target2").setDrillDownDragDrop(true);
};

// Drag 가 시작된 GridView(target1)에 설정한 사용자 정의 함수.
// DrillDown 환경에서는 첫번째 파라미터로 info 객체 하나가 전달되며, true 를 반환할 때만 Drop 이 진행된다.
scwin.target1_dragStartFunc = function (info) {
    scwin.setReturnValue("[dragStartFunction 호출] info.parentRowIndex : " + info.parentRowIndex);
    scwin.setReturnValue("[dragStartFunction 호출] info.parentRowData : " + JSON.stringify(info.parentRowData));
    scwin.setReturnValue("[dragStartFunction 호출] info.beforeRemoveRowIndex : " + JSON.stringify(info.beforeRemoveRowIndex));
    scwin.setReturnValue("[dragStartFunction 호출] info.beforeRemoveData : " + JSON.stringify(info.beforeRemoveData));
    return true;
};

// 두 그리드의 전체 Row 를 출력 (접혀서 화면에 보이지 않는 자식 Row 까지 트리 순서로 포함)
scwin.printGrid = function (strDltId, strTitle) {
    var arr = $p.getComponentById(strDltId).getAllJSON();
    scwin.setReturnValue("===== " + strTitle + " 전체 " + arr.length + "행 (접힌 자식 포함, 트리 순서) =====");
    for (var i = 0; i < arr.length; i++) {
        scwin.setReturnValue("  " + i + " : name=" + arr[i].name
            + ", dept=" + arr[i].dept
            + ", depth=" + arr[i].depth);
    }
};

scwin.btn_printData_onclick = function (e) {
    scwin.printGrid("dlt_bind1", "[target1 / Drag 소스]");
    scwin.printGrid("dlt_bind2", "[target2 / Drop 대상]");
};
